from audit_utils import *
for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/182.tex'
 def r(a,b,line,statement='',kind='reading',why='',count=1,full=False):
  replace(rel,a,b,layer,'182-217',line,statement,'400-dpi full scan and all three enlarged bands. '+why,kind,count=count,full=full)
 s=read(rel);a=s.index('Soit $L\'\'=');b=s.index('\\src{218}')+len('\\src{218}')
 old=s[a:b];new='\\src{218}\n'+old.replace('\\src{218}','').rstrip()
 if b>a:r(old,new,'page boundary after the tensor-product display','8',kind='structure',why='Page 217 ends with the tensor-product display; the paragraph beginning Soit L-double-prime belongs to page 218.',full=True)
 r(r'\kappa',r'\varkappa','opening paragraph','8-thm12-cor2',why='Both residue-field symbols have the crossed kappa form.',count=2)
 r(r'\Osh','O','discrete valuation ring','8',why='The local ring uses plain O.')
 r('toujours bijectif,','toujours \\uline{bijectif,}','opening line','8-thm12-cor2',why='Bijectif and its comma are underlined.')
 r('une majoration du\n$\\pi_1$','une \\uline{majoration} du\n$\\pi_1$','opening paragraph','8-thm12-cor2',why='This second occurrence of majoration is underlined.')
 r('(théorème 9, corollaire 4), on trouve par\nvoie transcendante :',r'(théorème 9, corollaire 4.) on trouve \uline{par'+ '\n'+r'voie transcendante} :','before Corollary 3','8-thm12-cor3',why='The period is inside the parenthesis, with no comma after it; par voie transcendante is underlined.')
 r(r'\textit{A priori}','A priori','descent of the covering','8',why='A priori is plain upright prose, not italicized.')
 r('On a alors : pour que','On a alors : Pour que','descent criterion','8',why='Pour begins with a capital P.')
 if tree=='fr_printed':
  r(r"\overline X'_1$ était",r"X'_1$ était",'Galois descent sentence','8-galois-descent',why='The printed X-prime_1 in the conditional has no overbar. Corrected French retains the overbar of the initially given geometric covering, as required by the intended descent assertion.')
 for label,n in [('COROLLAIRE',3),('COROLLAIRE',4)]:
  txt,_,_=page_text(rel,217);marker='\\result{'+label+'}{'+str(n)+'} ';a=txt.index(marker)+len(marker);b=txt.find('\n\n',a);old=txt[a:b]
  r(old,underline_prose(old),label+' '+str(n)+' prose','8-thm12-cor'+str(n),why='The statement prose is underlined, mathematical symbols and final period are not.')
 txt,_,_=page_text(rel,217);a=txt.index('Pour que');b=txt.index(' Supposons par exemple',a);old=txt[a:b]
 r(old,underline_prose(old),'finite-extension criterion','8',why='The criterion prose is underlined while the mathematical expressions and final period are plain.')
 upright_page(rel,layer,'182-217')
event('182-8-thm12-cor2','carried as background without fault found','Read the specialization-surjectivity consequence and its use on page 217. The construction of the geometric specialization map uses lifting finite étale covers over a henselian trait, strict henselization and finite-presentation descent; these inputs are carried as background here. Page 217 does not itself supply their full proof. The asserted improvement in characteristic zero remains conditional on the ramification argument that follows.','182, pp. 216–217, Corollary 2 and opening paragraph')
event('182-8-thm12-cor3','targeted proof check','Conditional deduction checked: lift the smooth proper curve to characteristic zero using Theorem 9 Corollary 4, use the surjective specialization map of Corollary 2, and transport the 2g generators of the characteristic-zero geometric fundamental group and their surface relation. The relation survives in a quotient; the wording does not assert that it is a complete presentation in positive characteristic. Characteristic-zero comparison with topology, descent to a finitely generated field and genus constancy in a smooth proper lift are background inputs.','182, p. 217, Corollary 3')
event('182-8-thm12-cor4','carried as background without fault found','Read the hyperplane-section deduction of finite topological generation. It needs a smooth connected complete-intersection curve whose geometric fundamental group surjects onto that of the smooth projective scheme, together with Corollary 3; the required Bertini and étale Lefschetz assertions are not proved on this page and are not independently established in this run.','182, p. 217, Corollary 4')
event('182-8-galois-descent','targeted proof check','The given covering at the start of the paragraph is geometric X-bar-prime_1. Its finite presentation, and the finitely many action maps and equalities of a finite Galois group, descend to some finite subextension of K-bar. Thus the antecedent for choosing a descended G-cover concerns X-bar-prime_1. Printed X-prime_1 omits the bar; corrected French retains it. The later finite-extension criterion follows from Theorem 12 and finite-presentation descent of the isomorphism between geometric generic-fiber covers. Conversely an étale cover over the extended complete trait restricts to a special-fiber cover. Descent of the special-fiber identification to the chosen geometric point is implicit in this reduction.','182, p. 217, Galois descent and underlined finite-extension criterion')
event('182-8-base-extension-normality','carried as background without fault found','Read the normality and function-field reduction under geometric normality of the special fiber. Normality in the neighborhood of the special fiber uses the flat normal-fiber criterion; properness over the local trait extends the conclusion globally. Finiteness and integrality of the normalization, and the interpretation of a single function field, use the connected/integral reduction implicit in this argument. The displayed four tensor products were checked by associativity and base-change identities.','182, p. 217, last paragraph and display')
record_page('182',217,r'''Compared sources/fr_printed/fr/182.tex and sources/fr/fr/182.tex entry lines 1164–1228 with scan leaf 26, rendered at 400 dpi, and all three enlarged bands. Read the specialization discussion, Corollaries 3 and 4, the finite-extension descent criterion and the final tensor-product identity. Moved the next-page marker before Soit L-double-prime, since the print ends at the displayed identity.

Restored the crossed kappas, plain local-ring O, selective underlining, upright A priori, capital Pour and the period inside the parenthesized reference to Theorem 9 Corollary 4. Printed French restores the missing geometric overbar in the Galois conditional as an omission; corrected French retains the bar because that conditional concerns the initially given geometric covering. The deduction of the curve generator statement is checked conditionally, including that a relation is preserved by a quotient without asserting a complete presentation in characteristic p. Specialization, Lefschetz, normality and descent background are explicitly distinguished from the elementary tensor identity and the descent-data check.''')
p='CHECK_RECORD.md';t=read(p).replace('## Open reading questions','- 182-217, Galois descent paragraph: confirmed the overbar on the given geometric cover in the conditional; the print omits it.\n\n## Open reading questions');write(p,t)
